css:
/* Visual Studio 2017: flat, square, blue-accented. */

/* Type: Segoe UI for chrome, Consolas for code (falls back off Windows). */
body { font-family: "Segoe UI", "Selawik", system-ui, -apple-system, "Helvetica Neue", sans-serif !important; }
.chat-markdown code, .chat-markdown pre, .chat-markdown-codeblock pre, .chat-markdown-codeblock code {
  font-family: Consolas, "Cascadia Mono", Menlo, Monaco, monospace !important;
}

/* Square corners everywhere, as in the VS shell. */
[data-slot="sidebar"], [data-slot="sidebar-inner"], [data-thread-item], [data-thread-item] *,
[data-chat-header], [data-user-message-bubble], .chat-markdown-codeblock, .chat-markdown code,
[data-thread-details-card], [data-thread-terminal-drawer],
[data-slot="button"], [data-slot="input"], [data-slot="select-trigger"],
[data-slot="switch"], [data-slot="switch"] *, [data-slot="project-monogram"],
[data-slot="dialog-popup"], [data-slot="popover-popup"], [data-slot="menu-popup"], [data-slot="menu-popup"] *,
[data-slot="tooltip-popup"], [data-slot="scroll-area-scrollbar"], [data-slot="scroll-area-thumb"],
[data-slot="composer-host"], [data-slot="composer-host"] *,
[data-slot="composer-host"]::before, [data-slot="composer-host"]::after,
[data-slot="composer-host"] *::before, [data-slot="composer-host"] *::after,
[data-chat-composer-form], [data-chat-composer-form] *,
[data-chat-composer-form]::before, [data-chat-composer-form]::after,
[data-chat-composer-form] *::before, [data-chat-composer-form] *::after {
  border-radius: 0 !important;
}
[data-slot="project-monogram"] svg rect { rx: 0; ry: 0; }

/* Sharp glyphs, like the VS icon set. */
svg.lucide { stroke-linecap: square; stroke-linejoin: miter; }

/* Solution Explorer density for thread rows. */
[data-thread-item] { min-height: 24px !important; padding-block: 1px !important; margin-block: 0 !important; }

/* Document well: the blue line under the tab strip. */
[data-chat-header] { border-bottom: 2px solid #007acc !important; box-shadow: none !important; }

/* Flat panels: borders, no shadows. */
[data-slot="composer-host"] { box-shadow: none !important; }
.dark [data-slot="composer-host"] { border: 1px solid #3f3f46 !important; }
:root:not(.dark) [data-slot="composer-host"] { border: 1px solid #cccedb !important; }
[data-slot="composer-host"]:focus-within { border-color: #007acc !important; }

.dark [data-user-message-bubble], .dark .chat-markdown-codeblock { border: 1px solid #3f3f46 !important; }
:root:not(.dark) [data-user-message-bubble], :root:not(.dark) .chat-markdown-codeblock { border: 1px solid #cccedb !important; }
.dark .chat-markdown-codeblock { background: #1e1e1e !important; }

/* Menus and popovers: flat with a soft drop shadow. Dialogs get the active-window accent border. */
.dark [data-slot="menu-popup"], .dark [data-slot="popover-popup"] {
  border: 1px solid #333337 !important; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.6) !important;
}
:root:not(.dark) [data-slot="menu-popup"], :root:not(.dark) [data-slot="popover-popup"] {
  border: 1px solid #cccedb !important; box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2) !important;
}
[data-slot="dialog-popup"] { border: 1px solid #007acc !important; box-shadow: 0 0 12px rgba(0, 0, 0, 0.5) !important; }

/* Tooltips. */
.dark [data-slot="tooltip-popup"] {
  background: #424245 !important; color: #f1f1f1 !important; border: 1px solid #4d4d50 !important; box-shadow: none !important;
}
:root:not(.dark) [data-slot="tooltip-popup"] {
  background: #ffffff !important; color: #1e1e1e !important; border: 1px solid #cccedb !important; box-shadow: none !important;
}

/* Scrollbars: grey thumb on a visible track. */
.dark ::-webkit-scrollbar { width: 12px; height: 12px; background: #3e3e42; }
.dark ::-webkit-scrollbar-thumb { background: #686868; border: 3px solid #3e3e42; }
.dark ::-webkit-scrollbar-thumb:hover { background: #9e9e9e; }
.dark ::-webkit-scrollbar-corner { background: #3e3e42; }
:root:not(.dark) ::-webkit-scrollbar { width: 12px; height: 12px; background: #e8e8ec; }
:root:not(.dark) ::-webkit-scrollbar-thumb { background: #c2c3c9; border: 3px solid #e8e8ec; }
:root:not(.dark) ::-webkit-scrollbar-thumb:hover { background: #686868; }
:root:not(.dark) ::-webkit-scrollbar-corner { background: #e8e8ec; }
.dark [data-slot="scroll-area-thumb"] { background: #686868 !important; }
:root:not(.dark) [data-slot="scroll-area-thumb"] { background: #c2c3c9 !important; }

/* Editor selection. */
.dark ::selection { background: #264f78; color: #ffffff; }
:root:not(.dark) ::selection { background: #add6ff; color: #1e1e1e; }

/* ---- Search surfaces: command palette, project search, file picker, model picker. ----
   Styled after VS Quick Launch / Go To All: accent window border, boxed search field,
   solid blue selection, status-bar footer. Row heights are left alone (lists are virtualized). */
[data-command-palette], [data-command-palette] *,
[data-command-palette] *::before, [data-command-palette] *::after,
[data-model-picker-content], [data-model-picker-content] *,
[data-model-picker-content] *::before, [data-model-picker-content] *::after,
[data-chat-provider-model-picker],
[data-slot$="-popup"], :has(> [data-slot$="-popup"]) {
  border-radius: 0 !important;
}

/* Window frame. */
[data-command-palette],
[data-slot$="-popup"]:has([data-model-picker-content]) {
  border: 1px solid #007acc !important;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.55) !important;
}
.dark [data-command-palette], .dark [data-slot$="-popup"]:has([data-model-picker-content]) { background: #252526 !important; }
:root:not(.dark) [data-command-palette], :root:not(.dark) [data-slot$="-popup"]:has([data-model-picker-content]) { background: #eeeef2 !important; }

/* Search field: a boxed VS text box that turns blue on focus. */
.dark [data-command-palette] [data-slot="autocomplete-input"],
.dark [data-model-picker-content] [data-slot="combobox-input"] {
  background: #333337 !important; color: #f1f1f1 !important; box-shadow: inset 0 0 0 1px #3f3f46 !important;
}
:root:not(.dark) [data-command-palette] [data-slot="autocomplete-input"],
:root:not(.dark) [data-model-picker-content] [data-slot="combobox-input"] {
  background: #ffffff !important; color: #1e1e1e !important; box-shadow: inset 0 0 0 1px #cccedb !important;
}
:root [data-command-palette] [data-slot="autocomplete-input"]:is(:focus, :focus-within),
:root [data-model-picker-content] [data-slot="combobox-input"]:is(:focus, :focus-within) {
  box-shadow: inset 0 0 0 1px #007acc !important; outline: none !important;
}

/* Highlighted result: solid accent with white text. */
[data-command-palette] :is([data-slot="command-item"], [data-slot="autocomplete-item"])[data-highlighted],
[data-model-picker-content] [data-slot="combobox-item"][data-highlighted] {
  background: #007acc !important; color: #ffffff !important;
}
[data-command-palette] :is([data-slot="command-item"], [data-slot="autocomplete-item"])[data-highlighted] *,
[data-model-picker-content] [data-slot="combobox-item"][data-highlighted] * {
  color: #ffffff !important;
}

/* Current model: the grey inactive selection. */
.dark [data-model-picker-content] [data-slot="combobox-item"][data-selected]:not([data-highlighted]) { background: #3f3f46 !important; }
:root:not(.dark) [data-model-picker-content] [data-slot="combobox-item"][data-selected]:not([data-highlighted]) { background: #cccedb !important; }

/* Category headers, as in Quick Launch results. */
[data-command-palette] [data-slot="command-group-label"] {
  font-size: 11px !important; font-weight: 600 !important; letter-spacing: 0 !important; text-transform: none !important;
}
.dark [data-command-palette] [data-slot="command-group-label"] { color: #f1f1f1 !important; box-shadow: inset 0 -1px 0 #3f3f46 !important; }
:root:not(.dark) [data-command-palette] [data-slot="command-group-label"] { color: #1e1e1e !important; box-shadow: inset 0 -1px 0 #cccedb !important; }

/* Footer: the blue status bar. */
[data-command-palette] [data-slot="command-footer"] {
  background: #007acc !important; border-top-color: #007acc !important; color: #ffffff !important;
}
[data-command-palette] [data-slot="command-footer"] * { color: #ffffff !important; }
[data-command-palette] [data-slot="command-footer"] [data-slot="kbd"] { background: rgba(255, 255, 255, 0.2) !important; }

/* Model picker provider rail: a vertical tool tab strip. */
.dark [data-model-picker-sidebar] { background: #2d2d30 !important; box-shadow: inset -1px 0 0 #3f3f46 !important; }
:root:not(.dark) [data-model-picker-sidebar] { background: #eeeef2 !important; box-shadow: inset -1px 0 0 #cccedb !important; }
[data-model-picker-selected-indicator] { background: #007acc !important; }
.dark [data-model-picker-provider] [aria-pressed="true"] { background: #3f3f46 !important; }
:root:not(.dark) [data-model-picker-provider] [aria-pressed="true"] { background: #c9def5 !important; }

/* Model picker trigger: a VS toolbar combo box. */
.dark [data-chat-provider-model-picker] { background: #333337 !important; box-shadow: inset 0 0 0 1px #434346 !important; }
:root:not(.dark) [data-chat-provider-model-picker] { background: #ffffff !important; box-shadow: inset 0 0 0 1px #cccedb !important; }
.dark [data-chat-provider-model-picker]:is(:hover, [aria-expanded="true"]) { background: #3f3f46 !important; box-shadow: inset 0 0 0 1px #007acc !important; }
:root:not(.dark) [data-chat-provider-model-picker]:is(:hover, [aria-expanded="true"]) { background: #c9def5 !important; box-shadow: inset 0 0 0 1px #007acc !important; }
